// Only metadata leaves n8n. Error messages are truncated and stripped of anything
// that looks like PHI, because upstream errors can echo request bodies.
const e = $json;
const scrub = (s) => String(s ?? '')
  .replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, '[EMAIL]')
  .replace(/\b\d{3}-\d{2}-\d{4}\b/g, '[SSN]')
  .replace(/\b\d{1,2}\/\d{1,2}\/\d{2,4}\b/g, '[DATE]')
  .replace(/\(?\b\d{3}\)?[-. ]\d{3}[-. ]\d{4}\b/g, '[PHONE]')
  .slice(0, 300);
return [{ json: {
  text: `DxReview workflow failed: ${e.workflow?.name} / node ${e.execution?.lastNodeExecuted}`,
  workflow_id: e.workflow?.id,
  execution_id: e.execution?.id,
  execution_url: e.execution?.url,
  error: scrub(e.execution?.error?.message),
  retry_of: e.execution?.retryOf ?? null,
}}];
